import{_ as a,o as l,c as t,a5 as r}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"净度瑕疵类型 (inclusion / blemish)","description":"","frontmatter":{"title":"净度瑕疵类型 (inclusion / blemish)","grading":"clarity-types"},"headers":[],"relativePath":"zh/grading/clarity-types.md","filePath":"zh/grading/clarity-types.md","lastUpdated":1790876393000}'),i={name:"zh/grading/clarity-types.md"};function s(n,e,o,d,c,h){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="净度瑕疵类型-inclusion-blemish" tabindex="-1">净度瑕疵类型 (inclusion / blemish) <a class="header-anchor" href="#净度瑕疵类型-inclusion-blemish" aria-label="Permalink to &quot;净度瑕疵类型 (inclusion / blemish)&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>宝石内含物 (inclusion) 与表面瑕疵 (blemish) 的种类、位置、数量、 可见性共同参与净度描述。同种特征在不同宝石中的意义不同，需要结合品种、 位置、耐久性和观察条件理解。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-clarity-types-zh"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-clarity-types-zh">边界与安全</h2><p>本页用于理解净度术语和观察维度，不提供仅凭某一种内含物判断价值或耐久性的结论。是否影响安全、透明度或市场评价，需要结合品种、位置、大小、方向和实际观察条件。 </p></aside><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>feather：羽状裂隙；耐久性影响取决于位置、是否达到表面、方向、大小和宝石品种。</li><li>cloud：云状包体，密集时影响透明度。</li><li>crystal / mineral：结晶包裹体（金红石、锆石、方解石）。</li><li>needle：金红石针状——蓝宝石&quot;丝绒感&quot;的关键。</li><li>blemish / chip / scratch：表面瑕疵。</li><li>位置会改变可见性、净度判断和耐久性风险，不能用单一倍数概括。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>祖母绿</td><td>jardin (3-phase)</td><td>品种语境中的内含物描述，仍需结合透明度和耐久性</td></tr><tr><td>红宝石</td><td>silk (rutile needles)</td><td>可能与星光效应相关，需结合方向、密度和切磨</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页用于理解分级描述和报告术语；来源说明知识依据，不代表仅凭本页即可完成具体样品分级、估值、鉴定或产地判断。</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA：钻石质量要素</a><span>钻石颜色、净度、切工与克拉重量等质量描述因素；不作为价格公式</span><small>打开来源 ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs：钻石净度</a><span>FL–I3 净度等级和 10× 观察条件的入门说明</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA：有色宝石价值要素与切工质量</a><span>不同品种的颜色、切工、净度、耐久性与市场因素需要综合理解</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA：祖母绿质量要素</a><span>祖母绿颜色、透明度、内含物和处理语境的品种化示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法</a><span>产地意见需要包裹体、微量元素等多维证据，并可能无法判定</span><small>打开来源 ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC：珠宝、贵金属与宝石指南</a><span>美国消费者与营销披露指南；不自动等同于所有地区的法律要求</span><small>打开来源 ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-clarity-types-zh"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-clarity-types-zh">本页证据映射</h2><p class="gem-reference-block__intro">把本页的教学主张映射到来源，并标注它在知识库中的证据状态。</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>同一种内含物在不同宝石中的意义不同，应结合品种、位置、可见性、耐久性和观察条件判断。</span><small>GIA 4Cs：钻石净度；GIA：祖母绿质量要素</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>羽状裂隙是否影响耐久性取决于位置、是否达到表面、方向、大小和宝石品种，不能仅凭名称断定。</span><small>GIA 4Cs：钻石净度；GIA：祖母绿质量要素</small></li></ul></aside><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',11)])])}const g=a(i,[["render",s]]);export{p as __pageData,g as default};
